from taf.sw.security.defensics.provider import DefensicsProvider


class DefensicsConnection(object):
    DEFAULT_TIMEOUT = 10

    def __init__(self, ip_address, port, token=None, defensics_version="defensics_v2020_3", secure=False):
        """
        Provides connection and authorization to Defensics.

        :param str ip_address: IP address to proper host, e.g. `10.44.44.1`.
        :param int port: Port for connection to Defensics, e.g. 5900.
        :param Optional[str] token: To prevent the service from being wide open to any callers, token authentication
            should be used. When defensics starts with flag --enable-token-auth it generates a token.
        :param Optional[str] defensics_version: Specifies version of the Defensics.
            Current possibilities: [`defensics_v2020_3`].
        :param Optional[bool] secure: If set to `True`, the connection will be realized with use https prefix,
            else with http. Currently only http can be used.
        """
        self._defensics_interface = DefensicsProvider.get_defensics_interface(
            ip_address=ip_address, port=port, token=token, defensics_version=defensics_version, secure=secure
        )

    def load_suite(self, suite_file, name=None, use_newest=True, timeout=DEFAULT_TIMEOUT):
        """
        Method for suite loading.

        :param str suite_file: name of suite e.g.: /opt/Synopsys/Defensics/bt-a2dp-5.3.0/testtool/bt-a2dp-530.jar
        :param Optional[str] name: if given suite can be controlled using shorter suite name
        :param Optional[bool] use_newest: If set to True, the newest installed suite will be loaded. Defaults to True
        :param Optional[int] timeout: Timeout for the operation.
        :return: It returns str with information that suite load process has started
        """
        return self._defensics_interface.load_suite(
            suite_file=suite_file, name=name, use_newest=use_newest, timeout=timeout
        )

    def get_installed_suites(self, timeout=DEFAULT_TIMEOUT):
        """
        Get list of all installed suites

        :param Optional[int] timeout: Timeout for the operation.
        :return: It returns list of currently installed suites
        """
        return self._defensics_interface.get_installed_suites(timeout=timeout)

    def start_plan(self, run_sequentially=False, timeout=DEFAULT_TIMEOUT):
        """
        Execute all loaded suites

        :param Optional[bool] run_sequentially: Determines if suites are executed one by one (`True`)
            or in parallel (`False`)
        :param Optional[int] timeout: Timeout for the operation
        :return:
        """

        return self._defensics_interface.start_plan(run_sequentially=run_sequentially, timeout=timeout)

    def stop_plan(self, timeout=DEFAULT_TIMEOUT):
        """
        Stop execution of the plan

        :param Optional[int] timeout: Timeout for the operation
        :return:
        """

        return self._defensics_interface.stop_plan(timeout=timeout)

    def start_suite(self, name=None, timeout=DEFAULT_TIMEOUT):
        """
        Execute a suite specified by its name. If there is only one suite loaded, name is not needed.

        :param Optional[str] name: Short name of the suite
        :param Optional[int] timeout: Timeout for the operation
        :return: str: Server's response message, e.g., `Test suite https started`
        """

        return self._defensics_interface.start_suite(name=name, timeout=timeout)

    def stop_suite(self, name=None, timeout=DEFAULT_TIMEOUT):
        """
        Stop execution of a suite specified by its name. If there is only one suite loaded, name is not needed.

        :param Optional[str] name: Short name of the suite
        :param Optional[int] timeout: Timeout for the operation
        :return:
        """

        return self._defensics_interface.stop_suite(name=name, timeout=timeout)

    def resume_suite(self, suite, test_run=None, resume_index_offset=None, timeout=DEFAULT_TIMEOUT):
        """
        Resume a stopped run. By default, suite's most recent test run is resumed. Suite must be loaded.

        :param str suite: ??
        :param Optional[str] test_run: Defines explicitly a test run to resume, e.g., HTTP-Server/20130201-1315-44
        :param Optional[int] resume_index_offset: Can be used to define where the resume is started,
            e.g., 10 resumes the defined test run 10 test cases ahead where it ended
        :param Optional[int] timeout: Timeout for the operation
        :return: str: Server's response message, e.g, `Test suite HTTP-Server's test run 20110207-0934-45 resumed`
        """

        return self._defensics_interface.resume_suite(
            suite=suite, test_run=test_run, resume_index_offset=resume_index_offset, timeout=timeout
        )

    def pause_suite(self, name=None, timeout=DEFAULT_TIMEOUT):
        """
        Pause a suite specified by its short name; it can be continued with `start_suite`.
        If there is only one suite loaded, name is not needed.

        :param Optional[str] name: Short name of the suite
        :param Optional[int] timeout: Timeout for the operation
        :return: str: Server's response message, e.g., `Test suite https paused`
        """
        return self._defensics_interface.pause_suite(name=name, timeout=timeout)

    def get_suite_status(self, name, timeout=DEFAULT_TIMEOUT):
        return self._defensics_interface.get_suite_status(name=name, timeout=timeout)

    def get_testing_status(self, timeout=DEFAULT_TIMEOUT):
        return self._defensics_interface.get_testing_status(timeout=timeout)

    def get_recent_result_of_plan(self, timeout=DEFAULT_TIMEOUT):
        return self._defensics_interface.get_recent_result_of_plan(timeout=timeout)

    def get_recent_result_of_suite(self, timeout=DEFAULT_TIMEOUT):
        return self._defensics_interface.get_recent_result_of_suite(timeout=timeout)

    def save_result(self, dest_dir, file_path, name=None, timeout=DEFAULT_TIMEOUT):
        return self._defensics_interface.get_result(dest_dir=dest_dir, file_path=file_path, name=name, timeout=timeout)

    def save_report(self, dest_dir, result_dir, report_type, timeout=DEFAULT_TIMEOUT):
        return self._defensics_interface.get_report(
            dest_dir=dest_dir, result_dir=result_dir, report_type=report_type, timeout=timeout
        )

    def rerun_suite(
        self,
        suite=None,
        suite_name=None,
        file_path=None,
        load_suite=None,
        setting=None,
        verdict=None,
        type_of_rerun=None,
        instrumentation=None,
        rerun_preceding=None,
        timeout=DEFAULT_TIMEOUT,
    ):
        return self._defensics_interface.rerun_suite(
            suite=suite,
            suite_name=suite_name,
            file_path=file_path,
            load_suite=load_suite,
            setting=setting,
            verdict=verdict,
            type_of_rerun=type_of_rerun,
            instrumentation=instrumentation,
            rerun_preceding=rerun_preceding,
            timeout=timeout,
        )

    def get_suite_settings(self, name, timeout=DEFAULT_TIMEOUT):
        return self._defensics_interface.get_suite_settings(name=name, timeout=timeout)

    def set_suite_settings(self, name, args, timeout=DEFAULT_TIMEOUT):
        return self._defensics_interface.set_suite_settings(name=name, timeout=timeout, args=args)

    def start_interoperability_probe(self, name=None, apply_flag=True, timeout=DEFAULT_TIMEOUT):
        return self._defensics_interface.start_interoperability_probe(name=name, apply_flag=apply_flag, timeout=timeout)

    def get_result_of_previous_interoperability_probe(self, timeout=DEFAULT_TIMEOUT):
        return self._defensics_interface.get_result_of_previous_interoperability_probe(timeout=timeout)

    def unload_suite(self, name, timeout=DEFAULT_TIMEOUT):
        return self._defensics_interface.unload_suite(name=name, timeout=timeout)

    def kill_server(self, timeout=DEFAULT_TIMEOUT):
        return self._defensics_interface.kill_server(timeout=timeout)

    def check_all_licenses(self, timeout=DEFAULT_TIMEOUT):
        return self._defensics_interface.check_all_licenses(timeout=timeout)

    def check_license(self, suite, timeout=DEFAULT_TIMEOUT):
        return self._defensics_interface.check_license(suite, timeout=timeout)

    def load_plan(self, plan, timeout=DEFAULT_TIMEOUT):
        return self._defensics_interface.load_plan(plan, timeout=timeout)

    def get_plan_status(self, timeout=DEFAULT_TIMEOUT):
        return self._defensics_interface.get_plan_status(timeout=timeout)
